// Byte code operations of the interpreter, dispatched from SmallInterpreter.execute() through the operations table.
// Operations work on the current context of the interpreter, and may replace it, for example on message sends and returns.
// The byte codes are generated by SmallEncoder.

class SmallOperations
{
	interface Operation
	{
		SmallObject perform( int param ) throws SmallException;
	}

	SmallInterpreter interpreter;
	MethodCache methodCache = new MethodCache();

	static final int doSpecialOperation = 15;
	int maxOperation = 25;
	Operation[] operations = new Operation[ maxOperation + 1 ];

	SmallOperations( SmallInterpreter aInterpreter )
	{
		interpreter = aInterpreter;

		operations[ 1 ] = this::pushInstanceVar;
		operations[ 2 ] = this::pushArgumentVar;
		operations[ 3 ] = this::pushTemporaryVar;
		operations[ 4 ] = this::pushLiteral;
		operations[ 5 ] = this::pushConstant;
		operations[ 6 ] = this::assignInstance;
		operations[ 7 ] = this::assignTemporary;
		operations[ 8 ] = this::markArguments;
		operations[ 9 ] = this::sendMessage;
		operations[ 10 ] = this::sendUnary;
		operations[ 11 ] = this::sendBinary;
		operations[ 12 ] = this::pushBlock;
		operations[ 13 ] = this::doPrimitive;
		operations[ 14 ] = this::pushClassVariable;
		// Below are the "special" operations, encoded with bytecode high = 15 and low = code [ 1 .. 11 ].
		// Now routed through the same operations table.
		operations[ 15 ] = this::returnSelf;
		operations[ 16 ] = this::returnStackTop;
		operations[ 17 ] = this::returnBlock;
		operations[ 18 ] = this::duplicateStackTop;
		operations[ 19 ] = this::popStackTop;
		operations[ 20 ] = this::branch;
		operations[ 21 ] = this::branchIfNotFalse;
		operations[ 22 ] = this::branchIfNotTrue;
		operations[ 25 ] = this::sendToSuper;
	}

	SmallObject perform( int operationNum, int param )
			throws SmallException
	{
		if( operationNum == doSpecialOperation )
			operationNum = doSpecialOperation + param - 1;     // Point to second part of operations table

		if( operationNum < 1 || operationNum > maxOperation )
			throw new SmallException( "Unrecognized operation code: " + operationNum, interpreter.context );

		Operation operation = operations[ operationNum ];
		if( operation == null )
			throw new SmallException( "Unrecognized operation code: " + operationNum, interpreter.context );

		return operation.perform( param );
	}

	// ==================================== Byte code operations

	// Operation# 1

	SmallObject pushInstanceVar( int index )
	{
		interpreter.context.stackPush( interpreter.context.getInstanceVars()[ index ] );
		return null;
	}

	// Operation# 2

	SmallObject pushArgumentVar( int index )
	{
		interpreter.context.stackPush( interpreter.context.getArgumentVars().data[ index ] );
		return null;
	}

	// Operation# 3

	SmallObject pushTemporaryVar( int index )
	{
		interpreter.context.stackPush( interpreter.context.getTemporaryVars()[ index ] );
		return null;
	}

	// Operation# 4

	SmallObject pushLiteral( int index )
	{
		interpreter.context.stackPush( interpreter.context.getLiteralVars()[ index ] );
		return null;
	}

	// Operation# 5

	SmallObject pushConstant( int param )
			throws SmallException
	{
		if( param >= 0 && param < interpreter.image.smallIntsLength ) {
			interpreter.context.stackPush( interpreter.image.smallInts[ param ] );
		} else {
			switch( param ) {
				case 10:
					interpreter.context.stackPush( interpreter.image.nilObject );
					break;
				case 11:
					interpreter.context.stackPush( interpreter.image.trueObject );
					break;
				case 12:
					interpreter.context.stackPush( interpreter.image.falseObject );
					break;
				default:
					throw new SmallException( "Unknown constant: " + param, interpreter.context );
			}
		}
		return null;
	}

	// Operation# 6

	SmallObject assignInstance( int param )
	{
		interpreter.context.getInstanceVars()[ param ] = interpreter.context.stackGetTop();
		return null;
	}

	// Operation# 7

	SmallObject assignTemporary( int param )
	{
		interpreter.context.getTemporaryVars()[ param ] = interpreter.context.stackGetTop();
		return null;
	}

	// Operation# 8
	// Pop arguments form stack, put them in array, push that array on the stack.

	SmallObject markArguments( int param )
	{
		SmallObject newArguments = new SmallObject( interpreter.image.arrayClass, param );
		SmallObject[] tempArgs = newArguments.data; // direct access to array
		while( param > 0 ) {
			tempArgs[ -- param ] = interpreter.context.stackPop();
		}
		interpreter.context.stackPush( newArguments );
		return null;
	}

	// Operation# 9

	SmallObject sendMessage( int messageSelectorIndex )
			throws SmallException
	{
		// save old context
		interpreter.context.argumentVars = interpreter.context.stackPop();
		interpreter.context.saveCodesPointer();
		interpreter.context.saveStackTop();

		// build new context
		SmallObject messageSelector = interpreter.context.getLiteralVars()[ messageSelectorIndex ];
		SmallObject method = methodCache.lookupOrSave( interpreter.context, messageSelector );

		interpreter.context = new SmallContext( interpreter.image, interpreter.context, interpreter.context.argumentVars, method );
		return null;
	}

	// Operation# 10
	// < self >
	// param: 0: isNil, 1: notNil

	SmallObject sendUnary( int param )
			throws SmallException
	{
		SmallObject self = interpreter.context.stackPop();
		SmallObject result;

		if( param == 0 )    // isNil
			result = self == interpreter.image.nilObject ? interpreter.image.trueObject : interpreter.image.falseObject;
		else if( param == 1 )   // notNil
			result = self != interpreter.image.nilObject ? interpreter.image.trueObject : interpreter.image.falseObject;
		else
			throw new SmallException( "Illegal sendUnary: " + param, interpreter.context );

		interpreter.context.stackPush( result );
		return null;
	}

	// Operation# 11
	// < self arg >
	// param: 0: "<", 1: "<=", 2: "+"
	// If self and arg are both a SmallInt, then an optimized version is done.

	SmallObject sendBinary( int param )
			throws SmallException
	{
		SmallObject arg = interpreter.context.stackPop();
		SmallObject self = interpreter.context.stackPop();

		if( self instanceof SmallInt && arg instanceof SmallInt ) {
			int selfInt = ( ( SmallInt ) self ).value;
			int argInt = ( ( SmallInt ) arg ).value;

			switch( param ) {
				case 0:     // <
					return interpreter.context.stackPush( selfInt < argInt ? interpreter.image.trueObject : interpreter.image.falseObject );
				case 1:     // <=
					return interpreter.context.stackPush( selfInt <= argInt ? interpreter.image.trueObject : interpreter.image.falseObject );
				case 2: {   // +
					int intSum = selfInt + argInt;
					long longSum = ( long ) selfInt + ( long ) argInt;
					if( intSum == longSum )
						return interpreter.context.stackPush( interpreter.image.newInteger( intSum ) );
				}
				default:
					throw new SmallException( "Illegal sendBinary int param : " + param, interpreter.context );
			}
		}

		// Mon optimized binary message.
		interpreter.context.argumentVars = new SmallObject( interpreter.image.arrayClass, 2 );
		interpreter.context.argumentVars.data[ 0 ] = self;
		interpreter.context.argumentVars.data[ 1 ] = arg;
		interpreter.context.saveCodesPointer();
		interpreter.context.saveStackTop();

		String messageSelector;
		switch( param ) {
			case 0:
				messageSelector = "<";
				break;
			case 1:
				messageSelector = "<=";
				break;
			case 2:
				messageSelector = "+";
				break;
			default:
				throw new SmallException( "Illegal sendBinary param : " + param, interpreter.context );
		}
		SmallByteArray messageSelectorObj = new SmallByteArray( null, messageSelector );
		interpreter.context.method = interpreter.context.lookupMethod( interpreter.context.getSelf().objClass, messageSelectorObj );
		interpreter.context = new SmallContext( interpreter.image, interpreter.context, interpreter.context.argumentVars, interpreter.context.method );

		return null;
	}

	// Operation# 12: < block >

	SmallObject pushBlock( int argumentLocation )
	{
		int gotoIndex = interpreter.context.nextCode();
		SmallBlock result = new SmallBlock( interpreter.context, argumentLocation );
		interpreter.context.stackPush( result );
		interpreter.context.codesPointer = gotoIndex;
		return result;
	}

	// Operation# 13: < arg1 arg2 ... >
	// Next byte code is primitive number.

	SmallObject doPrimitive( int argCount )
			throws SmallException
	{
		int primitiveNum = interpreter.context.nextCode();

		SmallObject result = interpreter.primitives.perform( primitiveNum, argCount );
		interpreter.context.stackPush( result );
		return result;
	}

	// Operation# 14: < >
	// param is index of class variable

	SmallObject pushClassVariable( int param )
	{
		interpreter.context.stackPush( interpreter.context.getSelf().objClass.data[ SmallClass.instVarCount + param ] );
		return null;
	}

	// Operation# 15: < >
	// param is not used.

	SmallObject returnSelf( int param )
	{
		SmallObject result = interpreter.context.getSelf();
		interpreter.context = interpreter.context.castOrConvert( interpreter.context.getPreviousContext() );

		if( ! interpreter.context.isNil() ) {
			interpreter.context.stackPush( result );
			interpreter.context.saveStackTop();
		}

		return result;
	}

	// Operation# 16: < arg >
	// param is not used.

	SmallObject returnStackTop( int param )
	{
		SmallObject result = interpreter.context.stackPop();
		interpreter.context = interpreter.context.castOrConvert( interpreter.context.getPreviousContext() );

		if( ! interpreter.context.isNil() ) {
			interpreter.context.stackPush( result );
			interpreter.context.saveStackTop();
		}

		return result;
	}

	// Operation# 17: < block >
	// param is not used.

	SmallObject returnBlock( int param )
	{
		SmallObject result = interpreter.context.stackPop();
		interpreter.context = interpreter.context.castOrConvert( interpreter.context.getCreatingPreviousContext() );

		if( ! interpreter.context.isNil() ) {
			interpreter.context.stackPush( result );
			interpreter.context.saveStackTop();
		}

		return result;
	}

	// Operation# 18: < self >
	// param is not used.

	SmallObject duplicateStackTop( int param )
	{
		SmallObject result = interpreter.context.stackGetTop();
		interpreter.context.stackPush( result );
		return result;
	}

	// Operation# 19: < arg >
	// param is not used.

	SmallObject popStackTop( int param )
	{
		interpreter.context.stackPop();
		return null;
	}

	// Operation# 20: < >
	// param is not used.
	// Next code is branch location.

	SmallObject branch( int param )
	{
		interpreter.context.codesPointer = interpreter.context.nextCode();
		return null;
	}

	// Operation# 21: < bool >
	// param is not used.
	// Next code is branch location.
	// This is called by 'bool ifFalse: [ block ]'.
	// *Only* if bool is false, the block will be evaluated, otherwise it is branched over.

	SmallObject branchIfNotFalse( int param )
	{
		int branchCodesPointer = interpreter.context.nextCode();
		SmallObject result = interpreter.context.stackPop();
		if( result != interpreter.image.falseObject )
			interpreter.context.codesPointer = branchCodesPointer;

		return null;
	}

	// Operation# 22: < bool >
	// param is not used.
	// Next code is branch location.
	// This is called by 'bool ifTrue: [ block ]'.
	// *Only* if bool is true, the block will be evaluated, otherwise it is branched over.

	SmallObject branchIfNotTrue( int param )
	{
		int branchCodesPointer = interpreter.context.nextCode();
		SmallObject result = interpreter.context.stackPop();
		if( result != interpreter.image.trueObject )
			interpreter.context.codesPointer = branchCodesPointer;

		return null;
	}

	// Operation# 23: < self? >
	// param is not used.
	// Next code message selector index.

	SmallObject sendToSuper( int param )
			throws SmallException
	{
		int messageSelectorIndex = interpreter.context.nextCode();

		// save old context
		interpreter.context.argumentVars = interpreter.context.stackPop();
		interpreter.context.saveStackTop();
		interpreter.context.saveCodesPointer();

		// build new context
		SmallObject[] oldLiteralVars = interpreter.context.getLiteralVars();
		SmallObject methodClass = interpreter.context.getMethodClass();
		SmallObject parentClass = methodClass.data[ 1 ];
		SmallObject method = interpreter.context.lookupMethod( parentClass, ( SmallByteArray ) oldLiteralVars[ messageSelectorIndex ] );
		interpreter.context = new SmallContext( interpreter.image, interpreter.context, interpreter.context.argumentVars, method );
		return null;
	}
}
